import { searchTodos } from './todo';
import { db } from './database';

jest.mock('./database');

describe('searchTodos', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should prevent SQL injection by using parameterized queries', async () => {
    const maliciousKeyword = "'; DROP TABLE todos; --";
    (db.query as jest.Mock).mockResolvedValue([]);

    await searchTodos(maliciousKeyword);

    // Verify the query uses parameters, not string concatenation
    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      expect.arrayContaining([expect.stringContaining(maliciousKeyword)])
    );
  });

  it('should return matching todos for valid keyword', async () => {
    const mockTodos = [
      { id: 'todo_1', title: 'Buy groceries', description: 'Milk and eggs', completed: false, createdAt: new Date() }
    ];
    (db.query as jest.Mock).mockResolvedValue(mockTodos);

    const result = await searchTodos('groceries');

    expect(result).toEqual(mockTodos);
    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('LIKE'),
      expect.arrayContaining(['%groceries%'])
    );
  });
});

import { searchTodosByStatus } from './todo';
import { db } from './database';

jest.mock('./database');

describe('searchTodosByStatus', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should prevent SQL injection by using parameterized queries', async () => {
    const maliciousStatus = "1 OR 1=1";
    (db.query as jest.Mock).mockResolvedValue([]);

    await searchTodosByStatus(maliciousStatus);

    // Should use parameterized query, not concatenation
    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      expect.arrayContaining([expect.anything()])
    );
  });

  it('should validate and convert string to boolean', async () => {
    (db.query as jest.Mock).mockResolvedValue([]);

    await searchTodosByStatus('true');

    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('completed = $1'),
      [true]
    );
  });

  it('should reject invalid status values', async () => {
    await expect(searchTodosByStatus('invalid'))
      .rejects.toThrow('Invalid status value');
    expect(db.query).not.toHaveBeenCalled();
  });
});

import { getTodosByUser } from './todo';
import { db } from './database';

jest.mock('./database');

describe('getTodosByUser', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should prevent SQL injection by using parameterized queries', async () => {
    const maliciousUserId = "' OR '1'='1";
    (db.query as jest.Mock).mockResolvedValue([]);

    await getTodosByUser(maliciousUserId);

    // Must use parameterized query for userId
    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      [maliciousUserId]
    );
  });

  it('should return only todos belonging to the specified user', async () => {
    const userId = 'user-123';
    const mockTodos = [
      { id: 'todo_1', title: 'User task', description: 'Test', completed: false, createdAt: new Date() }
    ];
    (db.query as jest.Mock).mockResolvedValue(mockTodos);

    const result = await getTodosByUser(userId);

    expect(result).toEqual(mockTodos);
    expect(db.query).toHaveBeenCalledWith(
      expect.stringMatching(/WHERE ut\.user_id = \$1/),
      ['user-123']
    );
  });

  it('should return empty array when user has no todos', async () => {
    (db.query as jest.Mock).mockResolvedValue([]);

    const result = await getTodosByUser('user-456');

    expect(result).toEqual([]);
  });
});

import { createTodo } from './todo';
import { db } from './database';

jest.mock('./database');

describe('createTodo', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should create a todo with sanitized input and parameterized query', async () => {
    const input = {
      title: '  <script>alert(1)</script>  ',
      description: 'Test "description"'
    };
    (db.query as jest.Mock).mockResolvedValue([]);

    const result = await createTodo(input);

    expect(result.title).toBe('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(result.description).toBe('Test &quot;description&quot;');
    expect(result.completed).toBe(false);
    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      expect.arrayContaining([expect.any(String), result.title, result.description, false, expect.any(Date)])
    );
  });

  it('should throw error when validation fails', async () => {
    const invalidInput = { title: '', description: 'test' };

    await expect(createTodo(invalidInput))
      .rejects.toThrow('Invalid todo input');
    expect(db.query).not.toHaveBeenCalled();
  });

  it('should handle missing description', async () => {
    const input = { title: 'Valid title', description: '' };
    (db.query as jest.Mock).mockResolvedValue([]);

    const result = await createTodo(input);

    expect(result.description).toBe('');
  });
});

import { getTodoById } from './todo';
import { db } from './database';

jest.mock('./database');

describe('getTodoById', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should return todo when found', async () => {
    const mockTodo = {
      id: 'todo_123',
      title: 'Test Todo',
      description: 'Description',
      completed: false,
      createdAt: new Date('2024-01-01')
    };
    (db.query as jest.Mock).mockResolvedValue([mockTodo]);

    const result = await getTodoById('todo_123');

    expect(result).toEqual(mockTodo);
    expect(db.query).toHaveBeenCalledWith(
      'SELECT * FROM todos WHERE id = $1',
      ['todo_123']
    );
  });

  it('should return null when todo not found', async () => {
    (db.query as jest.Mock).mockResolvedValue([]);

    const result = await getTodoById('nonexistent');

    expect(result).toBeNull();
  });

  it('should use parameterized query to prevent SQL injection', async () => {
    const maliciousId = "123' OR '1'='1";
    (db.query as jest.Mock).mockResolvedValue([]);

    await getTodoById(maliciousId);

    expect(db.query).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      [maliciousId]
    );
  });
});

