describe('validateTodoInput - edge cases', () => {
  it('should return false for whitespace-only title', () => {
    const input = { title: '   ', description: 'test' };
    expect(validateTodoInput(input)).toBe(false);
  });

  it('should return true when description is missing', () => {
    const input = { title: 'Valid', description: '' };
    expect(validateTodoInput(input)).toBe(true);
  });

  it('should return true for exactly 200 character title', () => {
    const input = { title: 'a'.repeat(200), description: 'test' };
    expect(validateTodoInput(input)).toBe(true);
  });

  it('should return true for exactly 1000 character description', () => {
    const input = { title: 'Valid', description: 'a'.repeat(1000) };
    expect(validateTodoInput(input)).toBe(true);
  });
});

import { createTodo } from './todo';
import { db } from './database';

jest.mock('./database');

describe('generateId uniqueness', () => {
  it('should generate unique IDs for concurrent todo creation', async () => {
    (db.query as jest.Mock).mockResolvedValue([]);
    const input = { title: 'Test', description: 'Test' };

    const todo1 = await createTodo(input);
    const todo2 = await createTodo(input);

    expect(todo1.id).not.toBe(todo2.id);
    expect(todo1.id).toMatch(/^todo_\d+_[a-z0-9]{7}$/);
    expect(todo2.id).toMatch(/^todo_\d+_[a-z0-9]{7}$/);
  });
});

